sandbox.inicial:
let tarefas = [];

function adicionar(texto) {
  tarefas.push({ texto, feita: false });   // muda o ARRAY
  render();                                 // redesenha a tela do array
}
function render() {
  // limpa e redesenha a lista inteira a partir de `tarefas`
}
adicionar('comprar pão');
console.log(tarefas.length);  // 1

function marcar(id) {
  const t = tarefas.find(t => t.id === id);
  if (t) t.feita = !t.feita;   // inverte
  render();
}
function remover(id) {
  tarefas = tarefas.filter(t => t.id !== id);  // array sem o alvo
  render();
}

function salvar() {
  localStorage.setItem('tarefas', JSON.stringify(tarefas));
}
function carregar() {
  try {
    const salvas = localStorage.getItem('tarefas');
    tarefas = salvas ? JSON.parse(salvas) : [];
  } catch {
    tarefas = [];   // dado corrompido não trava o app
  }
}
